from torch.utils.cpp_extension import load_inline

# CUDA source implementing exact GELU for fp16 tensors
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

template <typename scalar_t>
__global__ void gelu_kernel(const scalar_t* __restrict__ input,
                            scalar_t* __restrict__ output,
                            size_t N) {
    const float sqrt_2 = 1.4142135623730951f;   // sqrt(2)
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    size_t stride = blockDim.x * gridDim.x;
    for (size_t i = idx; i < N; i += stride) {
        // Convert to float for computation
        float x = static_cast<float>(input[i]);
        // Exact GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
        float y = 0.5f * x * (1.0f + erff(x / sqrt_2));
        // Cast back to original type
        output[i] = static_cast<scalar_t>(y);
    }
}

at::Tensor gelu_fp16(at::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "gelu_fp16: input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::kHalf, "gelu_fp16: input must be fp16");

    auto output = torch::empty_like(input);
    const size_t N = input.numel();

    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "gelu_fp16", ([&] {
        gelu_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            N);
    }));

    // Synchronize and report any launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("gelu_fp16 CUDA launch error: %s\\n", cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gelu_fp16", &gelu_fp16, "Exact GELU activation for fp16 (CUDA)");
}
'''

# Build the inline extension
gelu_mod = load_inline(name='gelu_fp16_mod',
                       cpp_sources='',
                       cuda_sources=cuda_src,
                       functions=['gelu_fp16'],
                       verbose=False)

